    if (tool.id === "open-graph") return `${base}<label>Canonical URL<input name="canonicalUrl" value="${esc(project.canonicalUrl)}" inputmode="url"></label><label>URL ảnh 1200×630<input name="imageUrl" value="${esc(project.imageUrl)}" inputmode="url"></label><label>Tên website<input name="siteName" value="${esc(project.siteName)}"></label>`;
    if (["youtube-thumbnail","vimeo-thumbnail"].includes(tool.id)) return `<label>URL hoặc ID video<input name="sourceUrl" value="${esc(project.sourceUrl)}" placeholder="Dán URL ${tool.id.startsWith("youtube") ? "YouTube" : "Vimeo"}"></label><p class="smt2-help">Chỉ đọc metadata và thumbnail công khai qua oEmbed; không tải video hoặc audio.</p>`;
