    if (tool.id === "social-character-counter") return `<label>Nền tảng<select name="socialProvider">${["instagram","facebook","tiktok","x","threads","linkedin","pinterest","reddit","telegram","discord","bluesky","mastodon"].map((item)=>`<option ${item===project.socialProvider?"selected":""}>${item}</option>`).join("")}</select></label><label>Nội dung<textarea name="caption" maxlength="63206" placeholder="Dán nội dung cần kiểm tra…">${esc(project.caption)}</textarea></label><p class="smt2-help">Đếm theo Unicode nên emoji và tiếng Việt không bị tính sai theo byte.</p>`;
    if (tool.id === "case-converter") return `<label>Kiểu chuyển đổi<select name="textMode">${[["sentence","Viết hoa câu"],["upper","CHỮ HOA"],["lower","chữ thường"],["title","Title Case"],["camel","camelCase"],["kebab","kebab-case"],["toggle","Đảo HOA/thường"]].map(([value,label])=>`<option value="${value}" ${value===project.textMode?"selected":""}>${label}</option>`).join("")}</select></label><label>Văn bản<textarea name="caption" maxlength="63206">${esc(project.caption)}</textarea></label>`;
    if (["whitespace-cleaner","hashtag-cleaner","unicode-font-styler","alt-text-checker"].includes(tool.id)) return `<label>${tool.id==="alt-text-checker"?"Alt text":"Văn bản"}<textarea name="${tool.id==="alt-text-checker"?"altText":"caption"}" maxlength="63206" placeholder="Dán nội dung cần xử lý…">${esc(tool.id==="alt-text-checker"?project.altText:project.caption)}</textarea></label>${tool.id==="unicode-font-styler"?`<label>Kiểu<select name="textStyle"><option value="bold" ${project.textStyle==="bold"?"selected":""}>Bold sans</option><option value="mono" ${project.textStyle==="mono"?"selected":""}>Monospace</option><option value="circle" ${project.textStyle==="circle"?"selected":""}>Khoanh tròn</option></select></label>`:""}`;
    if (tool.id === "username-link-builder") return `<label>Nền tảng<select name="socialProvider">${["instagram","tiktok","x","threads","youtube","linkedin","pinterest","telegram","facebook"].map((item)=>`<option ${item===project.socialProvider?"selected":""}>${item}</option>`).join("")}</select></label><label>Username<input name="title" value="${esc(project.title)}" placeholder="hoang8"></label>`;
    if (["whatsapp-link","telegram-link","social-share-link"].includes(tool.id)) { const providers=tool.id==="whatsapp-link"?["whatsapp"]:tool.id==="telegram-link"?["telegram"]:["facebook","x","linkedin","reddit","email"],selected=providers.includes(project.shareProvider)?project.shareProvider:providers[0]; return `<label>Nền tảng<select name="shareProvider">${providers.map((item)=>`<option ${item===selected?"selected":""}>${item}</option>`).join("")}</select></label>${tool.id==="whatsapp-link"?`<label>Số điện thoại gồm mã quốc gia<input name="phone" value="${esc(project.phone)}" inputmode="tel" placeholder="84901234567"></label>`:""}<label>URL HTTPS<input name="canonicalUrl" value="${esc(project.canonicalUrl)}" inputmode="url"></label><label>Nội dung<textarea name="caption" maxlength="4000">${esc(project.caption)}</textarea></label>`; }
