  const assetDb=()=>new Promise((resolve,reject)=>{if(!root.indexedDB)return reject(new Error("IndexedDB không được hỗ trợ."));const open=indexedDB.open("hh-social-media-assets-v1",1);open.onupgradeneeded=()=>open.result.createObjectStore("assets");open.onsuccess=()=>resolve(open.result);open.onerror=()=>reject(open.error);});
  async function assetRecord(action,key,value){const db=await assetDb();return new Promise((resolve,reject)=>{const tx=db.transaction("assets",action==="get"?"readonly":"readwrite"),store=tx.objectStore("assets"),req=action==="put"?store.put(value,key):action==="delete"?store.delete(key):store.get(key);req.onsuccess=()=>resolve(req.result);req.onerror=()=>reject(req.error);tx.oncomplete=()=>db.close();});}
  const assetKey=(asset)=>`${app.state.project.ownerId}:${app.state.workspaceId}:${asset.id}`;
  async function sanitizeAsset(file,mime){if(mime!=="image/svg+xml")return file;const parsed=new DOMParser().parseFromString(await file.text(),"image/svg+xml");if(parsed.querySelector("parsererror,script,foreignObject,iframe,object,embed"))throw new Error("SVG chứa thành phần không an toàn.");parsed.querySelectorAll("*").forEach((node)=>[...node.attributes].forEach((attr)=>{if(/^on/i.test(attr.name)||/^(?:javascript|data:text\/html)/i.test(attr.value))node.removeAttribute(attr.name);if(["href","xlink:href"].includes(attr.name)&&!attr.value.startsWith("#"))node.removeAttribute(attr.name);}));return new Blob([new XMLSerializer().serializeToString(parsed.documentElement)],{type:mime});}
  async function addFiles(files){let added=0;const existing=new Set(app.state.project.assets.map(a=>a.sha256));for(const file of [...files].slice(0,100)){const hardLimit=file.type.startsWith("video/")?2*1024*1024*1024:50*1024*1024;if(file.size>hardLimit){toast(`${file.name} vượt giới hạn an toàn.`,"warn");continue;}const check=await Core().detectMime(file);if(!check.allowed){toast(`${file.name}: loại file không khớp nội dung.`,"warn");continue;}try{const blob=await sanitizeAsset(file,check.detected),sha=await Core().sha256(await blob.arrayBuffer());if(existing.has(sha)){toast(`${file.name}: đã bỏ qua file trùng checksum.`,"warn");continue;}const meta=await Pipeline().inspectFile(blob),asset={id:`asset-${Date.now()}-${Math.random().toString(36).slice(2,8)}`,name:Core().filename(file.name,file.name.split(".").pop()),mimeType:check.detected,size:blob.size,sha256:sha,sourceType:"user-upload",rightsConfirmed:false,commercialUseConfirmed:false,thirdPartyElementsReviewed:false,metadata:meta,url:URL.createObjectURL(blob)};await assetRecord("put",assetKey(asset),blob);await Pipeline().createCheckpoint({asset,meta,ownerId:app.state.project.ownerId,workspaceId:app.state.workspaceId});app.state.project.assets.push(asset);existing.add(sha);added++;}catch(error){toast(`${file.name}: ${error.message}`,"warn");}}updateProject({assets:app.state.project.assets,activeAsset:Math.max(0,app.state.project.assets.length-added)},"Thêm asset");rerender();toast(`Đã thêm ${added} file; cần xác nhận quyền trước khi xuất bản.`);}
  async function hydrateAssets(){for(const asset of app.state.project.assets)if(!asset.url)try{const blob=await assetRecord("get",assetKey(asset));if(blob)asset.url=URL.createObjectURL(blob);}catch{}renderAssets();}

  async function saveCloud(){if(!app.options.currentUser?.id)return null;const p=app.state.project;return request(`projects?workspaceId=${encodeURIComponent(app.state.workspaceId)}`,{method:"POST",body:JSON.stringify({workspaceId:app.state.workspaceId,projectId:p.id,title:p.title,toolId:p.toolId,platform:p.platform,payload:{caption:p.caption,altText:p.altText,ratio:p.ratio,theme:p.theme,assets:p.assets.map(({url,...asset})=>asset)}})});}
  async function loadBackend(preferred=""){if(!app.options.currentUser?.id)return;try{const workspaces=await request("workspaces");app.state.workspaces=workspaces.items;app.state.workspaceId=workspaces.items.some((item)=>item.workspaceId===preferred)?preferred:workspaces.items[0]?.workspaceId||"personal";app.store=Core().createStore({currentUser:app.options.currentUser,workspaceId:app.state.workspaceId});app.state.project=app.store.get();const [accounts,jobs]=await Promise.all([request(`accounts?workspaceId=${app.state.workspaceId}`),request(`publish?workspaceId=${app.state.workspaceId}`)]);app.state.accounts=accounts.items;app.state.providers=accounts.providers||{};app.state.jobs=jobs.items;rerender();hydrateAssets();}catch(error){toast(`Chế độ local: ${error.message}`,"warn");}}
  async function startOAuth(provider){if(!app.options.currentUser?.id)throw new Error("Hãy đăng nhập HH Platform trước khi kết nối tài khoản.");const endpoints={facebook:"/api/facebook/oauth/start",tiktok:"/api/tiktok/oauth/start",youtube:"/api/youtube/oauth/start"},body={returnTo:location.origin,returnHash:"#/social-media-tools"};if(provider==="tiktok")body.scopes=["user.info.basic","user.info.profile","user.info.stats","video.list","video.upload","video.publish"];if(provider==="youtube")body.permissionPreset="creator";const response=await fetch(endpoints[provider],{method:"POST",credentials:"include",cache:"no-store",headers:{"Content-Type":"application/json",...(root.HHAuthSession?.token?.()?{Authorization:`Bearer ${root.HHAuthSession.token()}`}:{})},body:JSON.stringify(body)}),data=await response.json().catch(()=>({}));if(!response.ok)throw new Error(data.error||`Không thể bắt đầu OAuth ${provider}.`);const allowed={facebook:/^https:\/\/(?:www\.)?facebook\.com\//i,tiktok:/^https:\/\/(?:www\.)?tiktok\.com\//i,youtube:/^https:\/\/accounts\.google\.com\//i};if(!allowed[provider].test(data.authorizeUrl||""))throw new Error("Nhà cung cấp không trả về URL OAuth hợp lệ.");sessionStorage.setItem("hh.social.oauth.pending",JSON.stringify({provider,workspaceId:app.state.workspaceId,startedAt:Date.now()}));location.assign(data.authorizeUrl);}

  function unicodeStyle(value, style="bold") {
    const styles={ bold:[0x1d5d4,0x1d5ee,0x1d7ec], mono:[0x1d670,0x1d68a,0x1d7f6], circle:[0x24b6,0x24d0,0x2460] },points=styles[style]||styles.bold;
    return [...String(value||"")].map((char)=>{const code=char.codePointAt(0);if(code>=65&&code<=90)return String.fromCodePoint(points[0]+code-65);if(code>=97&&code<=122)return String.fromCodePoint(points[1]+code-97);if(code>=49&&code<=57)return String.fromCodePoint(points[2]+code-49);if(code===48&&style!=="circle")return String.fromCodePoint(points[2]+9);return char;}).join("");
  }
  async function paletteFromActiveAsset() {
    const asset=app.state.project.assets[app.state.project.activeAsset||0]; if(!asset?.url||!asset.mimeType.startsWith("image/"))throw new Error("Hãy tải và chọn một ảnh trước.");
    const image=await loadImage(asset.url),canvas=document.createElement("canvas"),ctx=canvas.getContext("2d",{willReadFrequently:true});canvas.width=64;canvas.height=64;ctx.drawImage(image,0,0,64,64);const data=ctx.getImageData(0,0,64,64).data,colors=new Map();
    for(let index=0;index<data.length;index+=16){if(data[index+3]<128)continue;const rgb=[data[index],data[index+1],data[index+2]].map((value)=>Math.min(255,Math.round(value/32)*32)),key=rgb.map((value)=>value.toString(16).padStart(2,"0")).join("").toUpperCase();colors.set(key,(colors.get(key)||0)+1);}
    return [...colors.entries()].sort((a,b)=>b[1]-a[1]).slice(0,5).map(([hex])=>`#${hex}`);
  }
  function resetActiveTool(){const current=activeTool(),previous=app.state.project,fresh=Core().defaultProject({currentUser:app.options.currentUser,workspaceId:app.state.workspaceId,id:previous.id});app.state.project=app.store.replace({...fresh,toolId:current.id,platform:platformFor(current),assets:previous.assets});rerender();toast("Đã đặt lại thiết lập công cụ.");}
  async function copyResult(){const value=app.lastResult?.text||app.host.querySelector("[data-smt2-output]")?.textContent?.trim();if(!value||value==="Chỉnh nội dung để bắt đầu.")throw new Error("Chưa có kết quả để sao chép.");await navigator.clipboard.writeText(value);toast("Đã sao chép kết quả.");}
