  const ENGINE_V5_IDS=new Set(["alt-text-checker","social-character-counter","case-converter","whitespace-cleaner","unicode-font-styler","hashtag-workspace","hashtag-cleaner","utm-builder","username-link-builder","whatsapp-link","telegram-link","social-share-link","youtube-timestamp","youtube-embed","open-graph","link-preview-audit","social-dimensions","caption-formatter","x-revenue"]);
  function outputText(result){if(typeof result==="string")return result;if(result?.output)return String(result.output);return JSON.stringify(result,null,2);}
  function rememberResult(tool,result){app.lastResult={toolId:tool.id,result,text:outputText(result),at:new Date().toISOString()};const history=[...(app.state.project.resultHistory||[]),{toolId:tool.id,text:app.lastResult.text.slice(0,12000),at:app.lastResult.at}].slice(-20);app.state.project=app.store.update((state)=>({...state,resultHistory:history}));}
  function applyResult(){const patch=app.lastResult?.result?.apply;if(!patch){toast("Kết quả này không có dữ liệu để áp dụng ngược.","warn");return;}updateProject(patch,"Áp dụng kết quả");rerender();toast("Đã áp dụng kết quả vào dự án.");}
  async function exportResult(format){if(!app.lastResult)throw new Error("Chưa có kết quả để xuất.");const tool=activeTool(),result=app.lastResult.result,name=Core().slug(`${tool.name}-${new Date().toISOString().slice(0,10)}`);if(format==="json")return saveBlob(new Blob([JSON.stringify(result,null,2)],{type:"application/json"}),`${name}.json`);if(format==="csv"){const value=result.csv||Engines().toCsv([["result"],[app.lastResult.text]]);return saveBlob(new Blob([value],{type:"text/csv;charset=utf-8"}),`${name}.csv`);}if(format==="txt")return saveBlob(new Blob([app.lastResult.text],{type:"text/plain;charset=utf-8"}),`${name}.txt`);if(format==="qr"){if(!root.QRCode?.toCanvas)throw new Error("Bộ tạo QR local chưa sẵn sàng.");const canvas=document.createElement("canvas");await root.QRCode.toCanvas(canvas,result.qrPayload||app.lastResult.text,{width:512,margin:2,color:{dark:"#07131fff",light:"#ffffffff"}});return saveBlob(await new Promise(resolve=>canvas.toBlob(resolve,"image/png")),`${name}-qr.png`);}if(["png","webp"].includes(format))return downloadImage();if(format==="zip")return exportKit();throw new Error(`Định dạng ${format.toUpperCase()} chưa hỗ trợ trong workspace này.`);}
  function savePreset(){const name=`${activeTool().name} · ${new Date().toLocaleString("vi-VN")}`,fields=Contracts().inputFields(activeTool()),values=Object.fromEntries(fields.map((field)=>[field,app.state.project[field]]));const presets=[...(app.state.project.presets||[]).filter((item)=>item.toolId!==activeTool().id),{id:`preset-${Date.now()}`,toolId:activeTool().id,name,values,createdAt:new Date().toISOString()}].slice(-30);updateProject({presets},"Lưu preset");toast("Đã lưu preset riêng cho công cụ.");}
  async function runWorkspaceEngine(tool,p){const kind=Workspaces().definitions[tool.id]?.kind;if(["x-composer","threads-composer"].includes(tool.id)){const parts=Core().splitThread(p.caption,tool.id==="x-composer"?"x":"threads");return{output:parts.map((part,index)=>`${index+1}/${parts.length}  ${part}`).join("\n\n"),parts,apply:{caption:parts.join("\n\n")}};}if(kind==="social-post")return{output:`${tool.name}\n${p.title}\n\n${p.caption}\n\nTỷ lệ ${p.ratio} · ${p.assets.length} asset`,platform:p.platform,ratio:p.ratio,assets:p.assets.map(({url,...asset})=>asset),apply:{platform:p.platform}};if(kind==="conversation")return{output:`BẢN MÔ PHỎNG ${tool.name.toUpperCase()}\nNgười tham gia: ${p.title}\nTin nhắn: ${p.caption}`,watermarked:true,apply:{caption:p.caption}};if(kind==="image-filter")return{output:`Bộ lọc ${p.theme}: sáng ${p.exposure}% · tương phản ${p.contrast}% · bão hòa ${p.saturation}% · blur ${p.blur}px`,settings:{exposure:p.exposure,contrast:p.contrast,saturation:p.saturation,temperature:p.temperature,blur:p.blur},assetId:p.assets[p.activeAsset||0]?.id||null};if(kind==="design")return{output:`${tool.name}\nTiêu đề: ${p.title}\nNội dung: ${p.caption}\nKhổ: ${p.ratio}`,design:{theme:p.theme,ratio:p.ratio},apply:{title:p.title,caption:p.caption}};if(kind==="bio-page")return{output:`${p.title}\n${p.caption}\n${p.canonicalUrl}`,links:[p.canonicalUrl],apply:{canonicalUrl:p.canonicalUrl}};if(kind==="emoji-board")return{output:p.caption||"Chọn emoji trên bảng để chèn.",apply:{caption:p.caption}};if(kind==="palette"){const colors=await paletteFromActiveAsset();return{output:colors.join("  "),colors};}if(kind==="export-package"){await exportKit();return{output:"Đã tạo Social Media Kit ZIP cùng rights manifest.",assets:p.assets.length};}throw new Error(`${tool.name} chưa có processor V5; trạng thái đã chuyển sang Đang phát triển.`);}

  async function runTool() {
    const tool=activeTool(),p=app.state.project,out=app.host.querySelector("[data-smt2-output]");
    try {
      const check=Contracts().validate(tool,p,contractContext());if(!check.valid)throw new Error(check.errors.map((item)=>item.message).join(" "));
      if(ENGINE_V5_IDS.has(tool.id)){const result=Engines().run(tool.id,p,{unicodeStyle});rememberResult(tool,result);out.textContent=outputText(result);renderWorkspaceResult(out.textContent);return;}
      if(tool.mode === "provider" && !["analytics","community-inbox"].includes(tool.id)){location.hash=`#${connectRoute(tool)}`;return;}
      if(tool.mode === "reuse"){const routes={"qr-campaign":"/tools/qr-barcode","subtitle-studio":"/davinci-resolve/davinci","video-resizer":"/davinci-resolve/davinci"};location.hash=`#${routes[tool.id]}`;return;}
      if(tool.id === "caption-formatter")out.textContent=Core().formatCaption({body:p.caption,hashtags:Core().captionStats(p.caption,p.platform).hashtags});
      else if(tool.id === "utm-builder")out.textContent=Core().buildUtm({url:p.canonicalUrl,source:p.utmSource,medium:p.utmMedium,campaign:p.utmCampaign});
      else if(tool.id === "open-graph"){const data=Core().buildOpenGraph({title:p.title,description:p.caption,url:p.canonicalUrl,image:p.imageUrl,siteName:p.siteName});out.textContent=`${data.html}\n\n<script type="application/ld+json">${JSON.stringify(data.jsonLd,null,2)}</script>`;}
      else if(tool.id === "x-revenue")out.textContent=JSON.stringify(Core().estimateXRevenue(p),null,2);
      else if(["x-composer","threads-composer"].includes(tool.id)){const parts=Core().splitThread(p.caption,tool.id==="x-composer"?"x":"threads");out.textContent=parts.map((part,index)=>`${index+1}/${parts.length}  ${part}`).join("\n\n");}
      else if(["youtube-thumbnail","vimeo-thumbnail"].includes(tool.id)){const provider=tool.id.startsWith("youtube")?"youtube":"vimeo",ref=Core().parseVideoRef(p.sourceUrl,provider);if(!ref)throw new Error(`URL hoặc ID ${provider} không hợp lệ.`);const data=await request(`oembed?workspaceId=${app.state.workspaceId}&provider=${provider}&url=${encodeURIComponent(ref.url)}`);out.textContent=`${data.title}\n${data.authorName}\n${data.thumbnailWidth}×${data.thumbnailHeight}\n${data.thumbnailUrl}\n\n${data.rights}`;}
      else if(tool.id === "repurpose"){const data=await request("ai",{method:"POST",body:JSON.stringify({workspaceId:app.state.workspaceId,action:p.aiAction||"repurpose",platform:p.platform,input:p.caption,brandVoice:p.brandVoice,sourceAssetIds:p.assets.map((asset)=>asset.id)})});const result={output:data.output,original:data.originalInput,contentStatus:data.contentStatus,approvalStatus:data.approvalStatus,autoPublish:false,warning:data.warning,apply:{caption:data.output}};rememberResult(tool,result);out.textContent=`BẢN GỐC\n${data.originalInput}\n\nBẢN AI · CẦN DUYỆT\n${data.output}\n\n${data.warning}`;}
      else if(["calendar","approval","publishing-queue"].includes(tool.id)){if(!app.options.currentUser?.id)throw new Error("Đăng nhập để dùng hàng đợi cloud. Bạn vẫn có thể Xuất ZIP ở chế độ khách.");await saveCloud();const data=await request("publish",{method:"POST",headers:{"Idempotency-Key":Core().idempotencyKey({ownerId:p.ownerId,workspaceId:app.state.workspaceId,projectId:p.id,accountId:p.accountId,provider:p.platform,scheduledAt:p.scheduledAt})},body:JSON.stringify({workspaceId:app.state.workspaceId,projectId:p.id,accountId:p.accountId,provider:p.platform,scheduledAt:p.scheduledAt,timezone:p.timezone,idempotencyKey:Core().idempotencyKey({ownerId:p.ownerId,workspaceId:app.state.workspaceId,projectId:p.id,accountId:p.accountId,provider:p.platform,scheduledAt:p.scheduledAt})})});app.state.jobs.unshift(data.item);out.textContent=`${data.message}\nRequest ID: ${data.item.requestId||"chưa gửi provider"}\nTrạng thái provider: ${data.item.providerStatus||"not-submitted"}\n${data.duplicatePrevented?"Đã chặn bản ghi trùng.":""}`;app.host.querySelector("[data-smt2-bottom-content]").innerHTML=bottomMarkup("queue");}
      else if(tool.id === "analytics"){if(!app.options.currentUser?.id)throw new Error("Đăng nhập và kết nối tài khoản để đọc analytics thật.");const data=await request(`analytics?workspaceId=${encodeURIComponent(app.state.workspaceId)}&accountId=${encodeURIComponent(p.accountId||"")}&provider=${encodeURIComponent(p.platform||"")}`);const result={items:data.items,nativeMetrics:data.nativeMetrics,aggregationPolicy:data.aggregationPolicy,syncedAt:data.syncedAt,source:data.source,csv:Engines().toCsv([["provider","nativeMetric","value","unit","syncedAt"],...data.items.map((item)=>[item.provider,item.nativeMetric,item.value,item.unit,item.syncedAt])])};rememberResult(tool,result);out.textContent=outputText(result);}
      else if(tool.id === "community-inbox"){if(!app.options.currentUser?.id)throw new Error("Đăng nhập và kết nối tài khoản để nhận webhook inbox thật.");const data=await request(`inbox?workspaceId=${encodeURIComponent(app.state.workspaceId)}&accountId=${encodeURIComponent(p.accountId||"")}`);const result={items:data.items,ownerIsolated:data.ownerIsolated,autoReply:false,source:data.source};rememberResult(tool,result);out.textContent=outputText(result);}
      else if(tool.id === "social-character-counter"){const data=Core().textMetrics(p.caption,p.socialProvider);out.textContent=`${data.characters}/${data.limit} ký tự · ${data.remaining} còn lại\n${data.words} từ · ${data.lines} dòng · ${data.bytes} byte\nKhoảng ${data.readingSeconds} giây đọc\n${data.hashtags.length} hashtag · ${data.mentions.length} mention · ${data.links.length} URL\nTrạng thái: ${data.valid?"Hợp lệ":"Vượt giới hạn"}`;}
      else if(tool.id === "case-converter")out.textContent=Core().transformText(p.caption,p.textMode);
      else if(tool.id === "whitespace-cleaner")out.textContent=Core().normalizeSocialText(p.caption);
      else if(tool.id === "unicode-font-styler")out.textContent=unicodeStyle(p.caption,p.textStyle);
      else if(tool.id === "hashtag-cleaner"){const result=Core().cleanHashtags(p.caption,30);out.textContent=`${result.text}\n\n${result.items.length} hashtag · đã loại ${result.removed} mục trùng`;
      }
      else if(tool.id === "username-link-builder")out.textContent=Core().profileUrl(p.socialProvider,p.title);
      else if(["whatsapp-link","telegram-link","social-share-link"].includes(tool.id))out.textContent=Core().buildShareUrl({provider:p.shareProvider,url:p.canonicalUrl,text:p.caption,title:p.title,phone:p.phone});
      else if(tool.id === "youtube-embed")out.textContent=Core().buildYouTubeEmbed(p.sourceUrl,{start:p.startSeconds,autoplay:p.autoplay}).html;
      else if(tool.id === "youtube-timestamp"){const ref=Core().parseVideoRef(p.sourceUrl,"youtube");if(!ref)throw new Error("URL hoặc ID YouTube không hợp lệ.");const url=new URL(ref.url);url.searchParams.set("t",`${Math.max(0,Math.floor(Number(p.startSeconds)||0))}s`);out.textContent=url.href;}
      else if(tool.id === "social-dimensions")out.textContent=Core().SOCIAL_DIMENSIONS.map((item)=>`${item.platform.padEnd(10)} ${item.asset.padEnd(18)} ${item.width}×${item.height} (${item.ratio})`).join("\n");
      else if(tool.id === "color-palette"){const palette=await paletteFromActiveAsset();out.textContent=palette.join("  ");out.innerHTML=`<span class="smt2-palette">${palette.map((hex)=>`<i style="--color:${hex}" title="${hex}"></i><b>${hex}</b>`).join("")}</span>`;}
      else if(tool.id === "link-preview-audit"){const data=Core().buildOpenGraph({title:p.title,description:p.caption,url:p.canonicalUrl,image:p.imageUrl,siteName:p.siteName});const warnings=[...data.warnings];if([...p.caption].length>160)warnings.push("Mô tả dài hơn 160 ký tự.");out.textContent=`${warnings.length?`CẢNH BÁO\n- ${warnings.join("\n- ")}\n\n`:"✓ Metadata bắt buộc đã hợp lệ\n\n"}${data.html}`;}
      else if(tool.id === "alt-text-checker"){const text=Core().normalizeSocialText(p.altText),issues=[];if(!text)issues.push("Alt text đang trống.");if([...text].length<20)issues.push("Mô tả có thể quá ngắn.");if([...text].length>200)issues.push("Nên rút gọn dưới khoảng 200 ký tự.");if(/^(ảnh|hình ảnh|photo|image)\s+(của|of)/i.test(text))issues.push("Không cần mở đầu bằng 'Ảnh của…' nếu ngữ cảnh đã rõ.");out.textContent=`${[...text].length} ký tự\n${issues.length?issues.map((item)=>`• ${item}`).join("\n"):"✓ Alt text có độ dài phù hợp; hãy kiểm tra nó mô tả đúng nội dung quan trọng."}`;}
      else if(Contracts().WORKSPACE_ENGINES.has(tool.id)){const result=await runWorkspaceEngine(tool,p);rememberResult(tool,result);out.textContent=outputText(result);renderDynamic();}
      else throw new Error(`${tool.name} đang phát triển; chưa có engine thật để chạy.`);
      if(!app.lastResult||app.lastResult.toolId!==tool.id)rememberResult(tool,{output:out.textContent});renderWorkspaceResult(out.textContent);
    } catch(error){out.textContent=`Không thể chạy: ${error.message}`;toast(error.message,"warn");}
  }
  function renderWorkspaceResult(value){const target=app.host.querySelector(".smw-editor-grid>section:last-child,.smw-url-builder .smw-empty,.smw-hashtag section:last-child,.smw-metadata section,.smw-video-code pre,.smw-empty");if(!target)return;target.classList.add("smw-result-ready");if(target.matches(".smw-metadata section"))return;target.innerHTML=`<small>KẾT QUẢ MỚI NHẤT</small><pre>${esc(value||"")}</pre><button type="button" data-smt2-copy>⧉ Sao chép</button>`;}
  function loadImage(url){return new Promise((resolve,reject)=>{const image=new Image();image.onload=()=>resolve(image);image.onerror=()=>reject(new Error("Không đọc được ảnh."));image.src=url;});}
  function wrap(ctx,text,x,y,max,line){let row="";for(const word of String(text||"").split(/\s+/)){const next=`${row} ${word}`.trim();if(ctx.measureText(next).width>max&&row){ctx.fillText(row,x,y);row=word;y+=line;}else row=next;}if(row)ctx.fillText(row,x,y);}
  async function renderCanvas(){const p=app.state.project,size=Core().cropSize(p.ratio,p.ratio==="9:16"?1080:1200),canvas=document.createElement("canvas"),ctx=canvas.getContext("2d");canvas.width=size.width;canvas.height=size.height;const grad=ctx.createLinearGradient(0,0,size.width,size.height);grad.addColorStop(0,"#6049df");grad.addColorStop(1,"#06121e");ctx.fillStyle=grad;ctx.fillRect(0,0,size.width,size.height);const asset=p.assets[p.activeAsset||0];if(asset?.url&&asset.mimeType.startsWith("image/")){const img=await loadImage(asset.url),scale=Math.max(size.width/img.naturalWidth,size.height/img.naturalHeight),dw=img.naturalWidth*scale,dh=img.naturalHeight*scale;ctx.save();ctx.filter=imageFilter(p);ctx.drawImage(img,(size.width-dw)/2,(size.height-dh)/2,dw,dh);ctx.restore();}if(p.vignette){const radial=ctx.createRadialGradient(size.width/2,size.height/2,Math.min(size.width,size.height)*.25,size.width/2,size.height/2,Math.max(size.width,size.height)*.7);radial.addColorStop(0,"transparent");radial.addColorStop(1,`rgba(0,0,0,${Math.min(.75,p.vignette/100)})`);ctx.fillStyle=radial;ctx.fillRect(0,0,size.width,size.height);}ctx.fillStyle="rgba(2,8,15,.64)";ctx.fillRect(0,size.height*.59,size.width,size.height*.41);ctx.fillStyle="#fff";ctx.font=`800 ${Math.round(size.width/17)}px sans-serif`;wrap(ctx,p.title,60,size.height*.7,size.width-120,Math.round(size.width/14));ctx.font=`${Math.round(size.width/34)}px sans-serif`;wrap(ctx,p.caption,60,size.height*.8,size.width-120,Math.round(size.width/25));if(["instagram-dm","whatsapp-mockup","imessage-mockup","tweet-card"].includes(activeTool().id)){ctx.fillStyle="#ffcf5a";ctx.fillRect(size.width-290,30,260,52);ctx.fillStyle="#151008";ctx.font="800 22px sans-serif";ctx.fillText("BẢN MÔ PHỎNG",size.width-270,64);}return canvas;}
  async function downloadImage(){const format=app.state.project.exportFormat||"png",mime=format==="jpg"?"image/jpeg":`image/${format}`,canvas=await renderCanvas(),link=document.createElement("a");link.download=Core().filename(app.state.project.title,format);link.href=canvas.toDataURL(mime,.92);link.click();}
  async function exportKit(){const p=app.state.project;if(!root.JSZip){saveBlob(new Blob([JSON.stringify(p,null,2)],{type:"application/json"}),"social-project.json");return;}const unconfirmed=p.assets.filter((asset)=>asset.rightsConfirmed!==true);if(unconfirmed.length)throw new Error(`${unconfirmed.length} asset chưa xác nhận quyền sử dụng; chưa thể đóng gói xuất bản.`);const zip=new root.JSZip();zip.file("caption.txt",p.caption);zip.file("metadata.json",JSON.stringify({title:p.title,altText:p.altText,platform:p.platform,ratio:p.ratio},null,2));zip.file("CREDITS.txt","Assets do người dùng cung cấp và đã xác nhận quyền. Xem RIGHTS-MANIFEST.json để đối chiếu.");zip.file("RIGHTS-MANIFEST.json",JSON.stringify(p.assets.map((asset)=>Pipeline().rightsManifest(asset,asset.metadata||{},p.ownerId,app.state.workspaceId)),null,2));zip.file("project.json",JSON.stringify({...p,assets:p.assets.map(({url,...asset})=>asset)},null,2));for(const asset of p.assets)if(asset.url)zip.file(`assets/${asset.name}`,await fetch(asset.url).then((response)=>response.blob()));if(Workspaces().definitions[activeTool().id]?.exportImage)zip.file(`${Core().slug(p.title)}-preview.png`,await new Promise((resolve)=>renderCanvas().then((canvas)=>canvas.toBlob(resolve,"image/png"))));saveBlob(await zip.generateAsync({type:"blob"}),`${Core().slug(p.title)}-social-kit.zip`);}
  async function exportMediaVariants(){const p=app.state.project,asset=p.assets[p.activeAsset||0];if(!asset?.url||!asset.mimeType.startsWith("image/"))throw new Error("Hãy chọn một ảnh để tạo biến thể.");if(!asset.rightsConfirmed)throw new Error("Cần xác nhận quyền asset trước khi xuất.");const source=await fetch(asset.url).then((response)=>response.blob()),zip=new root.JSZip();for(const target of Pipeline().TARGETS){const item=await Pipeline().imageVariant(source,target,{type:"image/webp",quality:.86});zip.file(`variants/${target.id}-${target.width}x${target.height}.webp`,item.blob);zip.file(`variants/${target.id}.json`,JSON.stringify({target:item.target,safeZone:item.safeZone,size:item.size,type:item.type},null,2));}zip.file("RIGHTS-MANIFEST.json",JSON.stringify(Pipeline().rightsManifest(asset,asset.metadata||{},p.ownerId,app.state.workspaceId),null,2));saveBlob(await zip.generateAsync({type:"blob"}),`${Core().slug(asset.name)}-social-variants.zip`);}
  function saveBlob(blob,name){const url=URL.createObjectURL(blob),link=Object.assign(document.createElement("a"),{href:url,download:name});link.click();setTimeout(()=>URL.revokeObjectURL(url),1000);}
  async function updateJob(jobId,action){try{const data=await request("publish",{method:"PATCH",body:JSON.stringify({workspaceId:app.state.workspaceId,jobId,action})}),index=app.state.jobs.findIndex((job)=>job.id===jobId);if(index>=0)app.state.jobs[index]=data.item;app.host.querySelector("[data-smt2-bottom-content]").innerHTML=bottomMarkup("queue");toast(`Đã chuyển sang ${data.item.state}.`);}catch(error){toast(error.message,"warn");}}

  function bind() {
    const host=app.host;
    host.addEventListener("click",async(event)=>{const button=event.target.closest("button");if(!button)return;
      if(button.hasAttribute("data-smt2-library")){host.querySelector("[data-smt2-library-dialog]").showModal();return;}
      if(button.hasAttribute("data-smt2-library-close")){host.querySelector("[data-smt2-library-dialog]").close();return;}
      if(button.dataset.smt2LibraryGroup){app.prefs.libraryGroup=button.dataset.smt2LibraryGroup;writePrefs();host.querySelector("[data-smt2-library-results]").innerHTML=libraryMarkup(host.querySelector("[data-smt2-library-search]")?.value||"");return;}
      if(button.dataset.smt2Group){app.prefs.group=button.dataset.smt2Group;app.prefs.expanded=false;writePrefs();rerender();return;}
      if(button.dataset.smt2Tool){host.querySelector("[data-smt2-library-dialog]")?.close();selectTool(button.dataset.smt2Tool);return;}
      if(button.dataset.smt2Favorite){const id=button.dataset.smt2Favorite;app.prefs.favorites=app.prefs.favorites.includes(id)?app.prefs.favorites.filter((item)=>item!==id):[...app.prefs.favorites,id];writePrefs();const sideSearch=app.host.querySelector("[data-smt2-search]");app.host.querySelector("[data-smt2-tool-results]").innerHTML=toolListMarkup(sideSearch?.value||"");const library=app.host.querySelector("[data-smt2-library-results]");if(library)library.innerHTML=libraryMarkup(library.querySelector("[data-smt2-library-search]")?.value||"");return;}
      if(button.hasAttribute("data-smt2-more")){app.prefs.expanded=!app.prefs.expanded;writePrefs();app.host.querySelector("[data-smt2-tool-results]").innerHTML=toolListMarkup();return;}
      if(button.dataset.smt2Mobile)host.querySelector(".smt2-layout").dataset.mobileView=button.dataset.smt2Mobile;
      if(button.dataset.smt2Preset){updateProject(PRESETS[button.dataset.smt2Preset],`Preset ${button.dataset.smt2Preset}`);return;}
      if(button.dataset.smt2Asset!==undefined){updateProject({activeAsset:Number(button.dataset.smt2Asset)},"Chọn asset");return;}
      if(button.dataset.smt2Move!==undefined){const from=Number(button.dataset.smt2Move),to=Math.max(0,Math.min(app.state.project.assets.length-1,from+Number(button.dataset.direction)));const assets=[...app.state.project.assets];[assets[from],assets[to]]=[assets[to],assets[from]];updateProject({assets,activeAsset:to},"Đổi thứ tự asset");rerender();return;}
      if(button.dataset.smt2Rights!==undefined){confirmAssetRights(Number(button.dataset.smt2Rights));return;}
      if(button.dataset.smt2Remove!==undefined){const asset=app.state.project.assets.splice(Number(button.dataset.smt2Remove),1)[0];if(asset){URL.revokeObjectURL(asset.url);assetRecord("delete",assetKey(asset)).catch(()=>{});}updateProject({assets:app.state.project.assets,activeAsset:0},"Xóa asset");rerender();return;}
      if(button.dataset.smt2Bottom){host.querySelectorAll("[data-smt2-bottom]").forEach((item)=>item.setAttribute("aria-pressed",item===button));host.querySelector("[data-smt2-bottom-content]").innerHTML=bottomMarkup(button.dataset.smt2Bottom);return;}
      if(button.dataset.smt2Job){await updateJob(button.dataset.smt2Job,button.dataset.action);return;}
      if(button.dataset.smt2Route){location.hash=`#${button.dataset.smt2Route}`;return;}
      if(button.dataset.smt2Oauth){try{button.disabled=true;button.textContent="Đang mở…";await startOAuth(button.dataset.smt2Oauth);}catch(error){button.disabled=false;button.textContent="Thử lại";toast(error.message,"warn");}return;}
      if(button.hasAttribute("data-smt2-connect")){location.hash=`#${connectRoute(activeTool())}`;return;}
      if(button.hasAttribute("data-smt2-accounts")){host.querySelector("[data-smt2-account-dialog]").showModal();return;}
      if(button.hasAttribute("data-smt2-run")){await runTool();return;}
      if(button.hasAttribute("data-smt2-apply")){applyResult();return;}
      if(button.dataset.smt2ResultExport){try{await exportResult(button.dataset.smt2ResultExport);}catch(error){toast(error.message,"warn");}return;}
      if(button.hasAttribute("data-smt2-preset-save")){savePreset();return;}
      if(button.hasAttribute("data-smt2-copy")){try{await copyResult();}catch(error){toast(error.message,"warn");}return;}
      if(button.hasAttribute("data-smt2-share")){try{await shareActiveTool();}catch(error){if(error.name!=="AbortError")toast(error.message,"warn");}return;}
      if(button.hasAttribute("data-smt2-reset")){resetActiveTool();return;}
      if(button.hasAttribute("data-smt2-report")){location.href=`mailto:nhhoang130803@gmail.com?subject=${encodeURIComponent(`Báo lỗi Social Tool: ${activeTool().name}`)}&body=${encodeURIComponent(`Công cụ: ${activeTool().id}\nURL: ${location.href}\n\nMô tả lỗi:\n`)}`;return;}
      if(button.dataset.smwEmoji){updateProject({caption:`${app.state.project.caption}${app.state.project.caption?" ":""}${button.dataset.smwEmoji}`},"Chèn emoji");return;}
      if(button.hasAttribute("data-smt2-download")){await downloadImage();return;}
      if(button.hasAttribute("data-smt2-export")){await exportKit();return;}
      if(button.hasAttribute("data-smt2-save")){try{await saveCloud();toast("Đã lưu phiên bản.");}catch(error){toast(`Đã lưu local: ${error.message}`,"warn");}return;}
      if(button.hasAttribute("data-smt2-undo")){undo();return;}
      if(button.hasAttribute("data-smt2-redo")){redo();return;}
    });
    host.addEventListener("input",(event)=>{if(event.target.matches("[data-smt2-search]")){host.querySelector("[data-smt2-tool-results]").innerHTML=toolListMarkup(event.target.value);return;}if(event.target.matches("[data-smt2-library-search]")){host.querySelector("[data-smt2-library-results]").innerHTML=libraryMarkup(event.target.value);host.querySelector("[data-smt2-library-search]")?.focus();return;}const form=event.target.closest("[data-smt2-form]");if(form)updateProject(formPatch(form),"Chỉnh nội dung");});
    host.addEventListener("change",(event)=>{if(event.target.matches("[data-smt2-files]"))addFiles(event.target.files);if(event.target.matches("[data-smt2-workspace]"))loadBackend(event.target.value);});
    const drop=host.querySelector("[data-smt2-drop]");if(drop){drop.addEventListener("dragover",(event)=>{event.preventDefault();drop.classList.add("is-dragging");});drop.addEventListener("dragleave",()=>drop.classList.remove("is-dragging"));drop.addEventListener("drop",(event)=>{event.preventDefault();drop.classList.remove("is-dragging");addFiles(event.dataTransfer.files);});}
  }
  function keydown(event){if(!app)return;if(event.key==="/"&&!/input|textarea|select/i.test(event.target.tagName)){event.preventDefault();const dialog=app.host.querySelector("[data-smt2-library-dialog]");(dialog?.open?dialog.querySelector("[data-smt2-library-search]"):app.host.querySelector("[data-smt2-search]"))?.focus();}if((event.ctrlKey||event.metaKey)&&event.key.toLowerCase()==="k"){event.preventDefault();app.host.querySelector("[data-smt2-library]")?.click();setTimeout(()=>app.host?.querySelector("[data-smt2-library-search]")?.focus(),0);}if((event.ctrlKey||event.metaKey)&&event.key.toLowerCase()==="s"){event.preventDefault();saveCloud().then(()=>toast("Đã lưu phiên bản.")).catch(()=>toast("Đã lưu local.","warn"));}if((event.ctrlKey||event.metaKey)&&event.key.toLowerCase()==="z"){event.preventDefault();app.host.querySelector(event.shiftKey?"[data-smt2-redo]":"[data-smt2-undo]")?.click();}if((event.ctrlKey||event.metaKey)&&event.key.toLowerCase()==="y"){event.preventDefault();app.host.querySelector("[data-smt2-redo]")?.click();}}
  function mount(rootHost,options={}){unmount();if(!rootHost||!Core()||!Workspaces()||!Contracts()||!Engines()||!Pipeline())throw new Error("Social Media Tools V5 dependencies missing.");const store=Core().createStore({currentUser:options.currentUser,workspaceId:"personal"}),project=store.get(),prefs=readPrefs(),projectTool=Core().TOOL_CATALOG.find((tool)=>tool.id===project.toolId);app={root:rootHost,host:null,options,store,prefs,lastResult:null,state:{project,workspaceId:project.workspaceId,workspaces:[{workspaceId:"personal",name:"Workspace cá nhân"}],accounts:[],providers:{},capabilities:{},jobs:[]}};if(projectTool&&!toolsForGroup(prefs.group).some((tool)=>tool.id===projectTool.id)){prefs.group=groupForTool(projectTool);writePrefs();}rootHost.innerHTML=shell();app.host=rootHost.firstElementChild;bind();renderDynamic();hydrateAssets();loadBackend();document.addEventListener("keydown",keydown);return{unmount,inspect};}
  function inspect(){return app?{mounted:true,version:5,contractVersion:Contracts().CONTRACT_VERSION,tools:Core().TOOL_CATALOG.length,toolId:app.state.project.toolId,group:app.prefs.group,workspaceId:app.state.workspaceId}:{mounted:false,version:5,tools:Core()?.TOOL_CATALOG?.length||0};}
  function unmount(){if(!app)return;clearTimeout(saveTimer);document.removeEventListener("keydown",keydown);app.state.project.assets.forEach((asset)=>asset.url&&URL.revokeObjectURL(asset.url));app.root.replaceChildren();app=null;}
  root.HHSocialMediaTools=Object.freeze({mount,unmount,inspect});
  if(typeof module!=="undefined"&&module.exports)module.exports=root.HHSocialMediaTools;
